{
 "paper_title": "Some Methods for Classification and Analysis of Multivariate Observations",
 "authors_year": "J. MacQueen, 1967",
 "research_question": "How can an N-dimensional population be partitioned into k sets on the basis of a sample using a computationally feasible process ('k-means'), and what is its asymptotic behavior?",
 "context": "The work stems from problems in optimal classification as formulated in optimal information structures and economic theory of organization and information, requiring feasible methods for partitioning multivariate observations.",
 "methods": [
  "Defining the k-means procedure starting with k groups of single random points and sequentially adding new points to the nearest mean with group mean adjustments",
  "Applying martingale theory (specifically Doob's martingale convergence theorems and Dubins-Savage inequalities) to study asymptotic behavior",
  "Computer experiments involving real data samples (college environment, semantic differential words, documents, physiological observations) using coarsening and refinement parameters",
  "Scrambled dimension tests for independence among variables",
  "Distance-based classification trees and two-step improvement procedures"
 ],
 "main_findings": [
  "The sequence of random variables W(xn) converges almost surely to V(x) for some x in the class of unbiased k-points (Theorem 1)",
  "The k-means procedure will not in general converge to an optimal partition, although there are special cases where it will",
  "Computer applications demonstrate that k-means combined with coarsening and refining parameters provides meaningful similarity groups and stable classifications",
  "The k-means concept can be extended to general metric spaces using sample centroids"
 ],
 "assumptions": [
  "Probability measure p is absolutely continuous with respect to Lebesgue measure on EN",
  "p(R) = 1 for a closed and bounded convex set R subset of EN, and p(A) > 0 for every open set A subset of R"
 ],
 "limitations_explicit": [
  "The k-means procedure in general will not converge to an optimal partition",
  "Convergence can sometimes oscillate slowly or converge to points where V(x) is not a strict minimum under certain symmetric distributions"
 ],
 "potential_open_questions": [
  {
   "question": "What is the exact power of the scrambled dimension test for independence?",
   "why_unresolved": "A computer program was not available to do the scrambling efficiently on large punched card sets, so further testing of this method was not undertaken.",
   "evidence": "A computer program was not available to do the scrambling, and its being inconvenient to set up large numbers of scrambled samples using punched cards, further testing of this method was not undertaken.",
   "sections": [
    "3.4"
   ]
  },
  {
   "question": "Can the possibility of the two means oscillating slowly but indefinitely around the center be eliminated in cases like the uniform distribution over a disk?",
   "why_unresolved": "Theorem 1 establishes convergence of the sum to zero but does not quite permit eliminating the slow indefinite oscillation around the center.",
   "evidence": "The k-means thus converge to some such relative position, but theorem 1 does not quite permit us to eliminate the interesting possibility that the two means oscillate slowly but indefinitely around the center.",
   "sections": [
    "2.3"
   ]
  }
 ],
 "candidate_hypotheses": [
  {
   "hypothesis": "For fixed marginal distributions, the within-class variance for the optimal partition is maximal when the joint distribution is actually the product of the marginals.",
   "evidence": "On the encouraging side is the related conjecture, that for fixed marginal distributions, the within-class variance for the optimal partition as defined in section 1 is maximal when the joint distribution is actually the product of the marginals.",
   "sections": [
    "3.4"
   ]
   }
  ]
}

